if(!UnityEditor.EditorApplication.isPlaying)throw new Exception("Play Mode required");UnityEditor.EditorApplication.isPaused=true;var runtime=UnityEngine.Object.FindFirstObjectByType<EchoSphere.Runtime.EchoSphereRuntime>();var t=runtime.GetType();var f=System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Public;
