void Equal(object a,object b,string path){if(a==null||b==null){if(a!=b)throw new Exception(path+" null");checks++;return;}if(a is string||a.GetType().IsPrimitive||a.GetType().IsEnum){if(!object.Equals(a,b))throw new Exception(path+" actual="+a+" expected="+b);checks++;return;}if(a is System.Collections.IEnumerable left&&b is System.Collections.IEnumerable right){var l=left.Cast<object>().ToArray();var r=right.Cast<object>().ToArray();if(l.Length!=r.Length)throw new Exception(path+" count");for(int i=0;i<l.Length;i++)Equal(l[i],r[i],path+"["+i+"]");return;}foreach(var field in a.GetType().GetFields(System.Reflection.BindingFlags.Public|System.Reflection.BindingFlags.Instance))Equal(field.GetValue(a),field.GetValue(b),path+"/"+field.Name);}
